#include <bits/stdc++.h>
using namespace std;

struct Node {
    bool term = false;
    unordered_map<string, Node*> children; // using UTF-8 substrings as keys (single codepoint bytes sequence)
};

// Split string into UTF-8 codepoint substrings
vector<string> utf8_chars(const string &s){
    vector<string> res;
    for(size_t i=0;i<s.size();){
        unsigned char c = s[i];
        size_t len = 1;
        if((c & 0x80) == 0) len = 1;
        else if((c & 0xE0) == 0xC0) len = 2;
        else if((c & 0xF0) == 0xE0) len = 3;
        else if((c & 0xF8) == 0xF0) len = 4;
        else len = 1;
        res.push_back(s.substr(i,len));
        i += len;
    }
    return res;
}

string escape_for_char_class(const string &cp){
    // cp is a UTF-8 char sequence; for simplicity if multi-byte return escaped sequence using \u{hex}
    if(cp.size() == 1){
        char c = cp[0];
        // inside char class, these must be escaped: ^ - ] \
        string s;
        if(c=='\\' || c==']' || c=='^' || c=='-' ) s += '\\', s += c;
        else if(c== '\n') s += "\\n";
        else if(c== '\r') s += "\\r";
        else if(c== '\t') s += "\\t";
        else if((unsigned char)c < 32 || (unsigned char)c == 127){
            char buf[10];
            sprintf(buf, "\\x%02x", (unsigned char)c);
            s = buf;
        } else {
            s += c;
        }
        return s;
    } else {
        // multi-byte -> use escape sequences \u{HEX}
        unsigned int codepoint = 0;
        // decode utf-8
        const unsigned char *bytes = (const unsigned char*)cp.c_str();
        if((bytes[0] & 0xF8) == 0xF0){
            codepoint = ((bytes[0]&0x07)<<18) | ((bytes[1]&0x3F)<<12) | ((bytes[2]&0x3F)<<6) | (bytes[3]&0x3F);
        } else if((bytes[0] & 0xF0) == 0xE0){
            codepoint = ((bytes[0]&0x0F)<<12) | ((bytes[1]&0x3F)<<6) | (bytes[2]&0x3F);
        } else if((bytes[0] & 0xE0) == 0xC0){
            codepoint = ((bytes[0]&0x1F)<<6) | (bytes[1]&0x3F);
        }
        char buf[64];
        sprintf(buf, "\\u{%x}", codepoint);
        return string(buf);
    }
}

string escape_literal(const string &s){
    // escape regex special characters
    string out;
    for(unsigned char c: s){
        if(c=='\\' || c=='.' || c=='+' || c=='*' || c=='?' || c=='^' || c=='$' || c=='(' || c==')' || c=='[' || c==']' || c=='{' || c=='}' || c=='|' ){
            out += '\\'; out += c;
        } else if(c=='\n') out += "\\n";
        else out += c;
    }
    return out;
}

string escape_cp_literal(const string &cp){
    if(cp.size()==1) return escape_literal(cp);
    // multi-byte return \u{hex}
    unsigned int codepoint = 0;
    const unsigned char *bytes = (const unsigned char*)cp.c_str();
    if((bytes[0] & 0xF8) == 0xF0){
        codepoint = ((bytes[0]&0x07)<<18) | ((bytes[1]&0x3F)<<12) | ((bytes[2]&0x3F)<<6) | (bytes[3]&0x3F);
    } else if((bytes[0] & 0xF0) == 0xE0){
        codepoint = ((bytes[0]&0x0F)<<12) | ((bytes[1]&0x3F)<<6) | (bytes[2]&0x3F);
    } else if((bytes[0] & 0xE0) == 0xC0){
        codepoint = ((bytes[0]&0x1F)<<6) | (bytes[1]&0x3F);
    }
    char buf[64]; sprintf(buf, "\\u{%x}", codepoint); return string(buf);
}

string build_pattern(Node* node, bool at_root, bool capture_groups){
    // collect alternatives
    vector<string> alts;
    if(node->term){
        alts.push_back("");
    }
    // for deterministic order, collect keys and sort by their byte-sequence
    vector<string> keys;
    for(auto &p: node->children) keys.push_back(p.first);
    sort(keys.begin(), keys.end(), [](const string &a, const string &b){ return a < b; });
    for(auto &k: keys){
        Node* child = node->children[k];
        string sub = build_pattern(child, false, capture_groups);
        string esc = escape_cp_literal(k);
        string combined = esc + sub;
        alts.push_back(combined);
    }
    if(alts.empty()) return string();

    // if single alternative, return it
    if(alts.size()==1) return alts[0];

    // check if all alts are single codepoint (after decoding) and none are empty
    bool all_single_cp = true;
    for(auto &a: alts){
        if(a.empty()){ all_single_cp = false; break; }
        // check if a represents exactly one codepoint and no escapes like \u
        // We'll approximate by checking utf8_chars count ==1 and that escaping didn't add backslashes
        auto cps = utf8_chars(a);
        if(cps.size()!=1) { all_single_cp = false; break; }
        // exclude if contains backslash
        if(a.find('\\')!=string::npos) { all_single_cp = false; break; }
    }
    if(all_single_cp){
        // build char class
        // collect unique chars
        set<string> uniq;
        for(auto &a: alts) uniq.insert(a);
        string cls = "";
        cls += '[';
        for(auto &c: uniq){
            cls += escape_for_char_class(c);
        }
        cls += ']';
        return cls;
    }

    // otherwise join with |
    string joined;
    for(size_t i=0;i<alts.size();++i){
        if(i) joined += '|';
        if(alts[i].empty()) joined += ""; // empty
        else joined += alts[i];
    }
    // wrap in group
    if(at_root) {
        // group still needed if multiple alternatives
        if(capture_groups) return string("(") + joined + ")";
        else return string("(?:") + joined + ")";
    } else {
        // wrap if contains | (it does)
        if(capture_groups) return string("(") + joined + ")";
        else return string("(?:") + joined + ")";
    }
}

int main(int argc, char** argv){
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    vector<string> args;
    for(int i=1;i<argc;i++) args.push_back(string(argv[i]));
    bool want_help=false, want_version=false;
    bool capture_groups=false;
    bool ignore_case=false;
    bool no_start_anchor=false, no_end_anchor=false;
    bool file_mode=false;
    string file_name;

    // simple parse
    for(size_t i=0;i<args.size();){
        string a = args[i];
        if(a=="-h" || a=="--help"){ want_help=true; i++; }
        else if(a=="-v" || a=="--version"){ want_version=true; i++; }
        else if(a=="-g" || a=="--capture-groups"){ capture_groups=true; i++; }
        else if(a=="-i" || a=="--ignore-case"){ ignore_case=true; i++; }
        else if(a=="--no-start-anchor"){ no_start_anchor=true; i++; }
        else if(a=="--no-end-anchor"){ no_end_anchor=true; i++; }
        else if(a=="--no-anchors"){ no_start_anchor = true; no_end_anchor = true; i++; }
        else if(a=="-f" || a=="--file"){ if(i+1<args.size()){ file_mode=true; file_name=args[i+1]; i+=2; } else i++; }
        else {
            // rest are inputs
            break;
        }
    }
    // handle help/version printing similar to original
    if(want_help){
        // print minimal help from README
        cout << "grex 1.4.6\n";
        cout << "© 2019-today Peter M. Stahl <pemistahl@gmail.com>\n";
        cout << "Licensed under the Apache License, Version 2.0\n";
        cout << "Downloadable from https://crates.io/crates/grex\n";
        cout << "Source code at https://github.com/pemistahl/grex\n\n";
        cout << "grex generates regular expressions from user-provided test cases.\n\n";
        cout << "Usage: grex [OPTIONS] {INPUT...|--file <FILE>}\n";
        return 0;
    }
    if(want_version){ cout << "grex 1.4.6\n"; return 0; }

    vector<string> inputs;
    // gather remaining args as inputs starting from first non-option
    size_t start=1;
    for(; start<(size_t)argc; ++start){ string a(argv[start]); if(a.size()>0 && a[0]=='-' && a!="-"){
            // options already handled earlier; skip option tokens and their values
            if(a=="-f" || a=="--file"){ start++; }
            continue;
        } else break; }
    // Instead better to reparse: collect any arg that is not an option taken
    // Simpler approach: iterate argv from 1..argc-1 and if not consumed as option add as input unless it's -f value
    set<int> consumed;
    for(int i=1;i<argc;i++){
        string a = argv[i];
        if(a=="-h"||a=="--help"||a=="-v"||a=="--version"||a=="-g"||a=="--capture-groups"||a=="-i"||a=="--ignore-case"||a=="--no-start-anchor"||a=="--no-end-anchor"||a=="--no-anchors") { consumed.insert(i); }
        else if(a=="-f" || a=="--file"){ consumed.insert(i); if(i+1<argc) consumed.insert(i+1); }
    }
    for(int i=1;i<argc;i++) if(!consumed.count(i)) inputs.push_back(string(argv[i]));

    // if file_mode
    if(file_mode){
        // read file_name; could be "-" meaning stdin
        istream *inptr = nullptr;
        if(file_name=="-"){
            // read from stdin
            string all; string line;
            vector<string> lines;
            while(getline(cin, line)) lines.push_back(line);
            for(auto &ln: lines) if(!ln.empty()) inputs.push_back(ln);
        } else {
            ifstream inf(file_name);
            if(!inf){ /* silently fail */ }
            string line;
            while(getline(inf, line)){
                if(!line.empty()) inputs.push_back(line);
            }
        }
    }

    // if no inputs provided, but stdin has data (piped) and there is a lone '-' among args or no args
    bool saw_dash=false;
    for(int i=1;i<argc;i++) if(string(argv[i])=="-") saw_dash=true;
    if(inputs.empty()){
        if(saw_dash || !isatty(fileno(stdin))){
            string line;
            vector<string> lines;
            while(getline(cin, line)) lines.push_back(line);
            if(lines.size()==0){ }
            else if(lines.size()==1) { inputs.push_back(lines[0]); }
            else { for(auto &ln: lines) if(!ln.empty()) inputs.push_back(ln); }
        }
    }

    // if still no inputs, nothing to do
    if(inputs.empty()) return 0;

    // build trie
    Node* root = new Node();
    for(auto &s: inputs){
        Node* cur = root;
        auto cps = utf8_chars(s);
        for(auto &cp: cps){
            if(cur->children.find(cp)==cur->children.end()) cur->children[cp] = new Node();
            cur = cur->children[cp];
        }
        cur->term = true;
    }

    string body = build_pattern(root, true, capture_groups);
    // If result is group with multiple alternatives and starts with (?:...)
    // Add anchors unless disabled
    string out;
    if(ignore_case) out += "(?i)";
    if(!no_start_anchor) out += "^";
    out += body;
    if(!no_end_anchor) out += "$";
    cout << out << "\n";
    return 0;
}
