            else for(auto &ln: lines) if(!ln.empty()) final_inputs.push_back(ln);
        } else final_inputs.push_back(inp);
    }
    inputs.swap(final_inputs);

    // if still no inputs, nothing to do
    if(inputs.empty()) return 0;
